#if UNITY_EDITOR
using System;
using System.Linq;
using System.Reflection;
using Unity.Netcode;
using Unity.Netcode.Transports.UTP;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
using Object=UnityEngine.Object;
[InitializeOnLoad]
public static class PartyFinaleValidation {
 const string Key="Party.Finale.Test",Result="Library/PartyFinale.validation";static int stage;static double at,deadline;static Vector3 crownPosition;static Quaternion crownRotation;static double expectedStart;static int lightIndex;static readonly string[] lightScenes={"CrosswalkRun","SawBladeDodge","TileFlip","Qte","BlockFall"};
 static PartyFinaleValidation(){EditorApplication.update+=Tick;Application.logMessageReceived+=(message,trace,type)=>{if(SessionState.GetBool(Key,false)&&type==LogType.Exception)Fail(new Exception(message+trace));};}
 static void Require(bool v,string message){if(!v)throw new Exception(message);}
 static void Tick(){try{
 if(System.IO.File.Exists("Library/PartyFinale.validate")&&!EditorApplication.isCompiling&&!EditorApplication.isUpdating&&!EditorApplication.isPlayingOrWillChangePlaymode){System.IO.File.Delete("Library/PartyFinale.validate");Prepare();return;}
 if(SessionState.GetBool("Party.Finale.Restore",false)&&!EditorApplication.isPlayingOrWillChangePlaymode){SessionState.SetBool("Party.Finale.Restore",false);EditorSceneManager.OpenScene(SessionState.GetString("Party.Finale.Previous","Assets/Scenes/Ranking.unity"));}
 if(!SessionState.GetBool(Key,false)||!EditorApplication.isPlaying||EditorApplication.isCompiling)return;
 var now=EditorApplication.timeSinceStartup;if(stage==0){deadline=now+170;at=now;stage=1;}Require(now<deadline,"Timed out stage "+stage);var network=NetworkManager.Singleton;
 if(stage==1){if(now-at<1)return;Application.runInBackground=true;network.GetComponent<UnityTransport>().SetConnectionData("127.0.0.1",17904);Require(network.StartHost(),"Host failed");at=now;stage=2;}
 else if(stage==2){if(PartyRoster.Current==null||!PartyRoster.Current.IsSpawned)return;Require(PartyGameRotation.StartSelected(network,"BlockFall",out var error),error);stage=3;}
 else if(stage==3){var guide=Object.FindObjectOfType<GameBriefing>();if(guide==null||PartyTicketTravel.Busy||guide.countdownText.text!="05")return;Require(guide.readingSeconds==5,"Guide duration is not five seconds");Require(guide.titleText.text.Contains("도서관"),"Wrong synchronized guide");Require(guide.rulesText.text.Contains("착지"),"Rules text missing");Capture("Library/GameBriefing-preview.png");at=now;stage=4;}
 else if(stage==4){if(SceneManager.GetActiveScene().name!="BlockFall"||PartyGameRotation.Loading||PartyTicketTravel.Busy)return;var game=Object.FindObjectOfType<BlockFall.BlockFallGame>();Require(game.CountdownRemaining>.15f&&game.CountdownRemaining<1.3f,"Actual start delay is not one second");Require(now-at>=5,"Guide ended too early");Require(PartyGameRotation.PlayedCount==1,"Game not committed");expectedStart=network.ServerTime.Time+game.CountdownRemaining;stage=9;}
 else if(stage==9){var game=Object.FindObjectOfType<BlockFall.BlockFallGame>();if(!game.HasRoundStarted)return;Require(network.ServerTime.Time-expectedStart<.4,"Game did not start at the one-second deadline");Require(!GameStartPresentation.BlocksGameplayInput,"Controls stayed locked after one second");var bag=(PartyGameBag)typeof(PartyGameRotation).GetField("bag",BindingFlags.NonPublic|BindingFlags.Static).GetValue(null);foreach(var scene in PartyGameRotation.Scenes)bag.Commit(scene);PartyRoster.Current.GamesStarted.Value=5;CrosswalkRun.RankingManager.Instance.AddScore(network.LocalClientId,"Winner",12);CrosswalkRun.RankingManager.Instance.AddScore(1,"하늘",9);CrosswalkRun.RankingManager.Instance.AddScore(2,"구름",6);CrosswalkRun.RankingManager.Instance.AddScore(3,"별빛",3);network.SceneManager.LoadScene(PartyGameRotation.ResultScene(),LoadSceneMode.Single);stage=5;}
 else if(stage==5){if(SceneManager.GetActiveScene().name!="FinalRanking")return;var final=Object.FindObjectOfType<FinalRanking>();if(final==null||PartyTicketTravel.Busy||Time.timeSinceLevelLoad<3||PartyRoster.Current.FinalReturnAt.Value<0||!final.winnerText.text.Contains("축하"))return;var crown=Object.FindObjectOfType<WinnerCrown>();Require(crown!=null,"Winner crown missing");var player=network.LocalClient.PlayerObject;Require(player!=null&&player.gameObject.scene.name=="FinalRanking"&&player.IsOwner,"Ceremony does not use owned network player");Require(player.transform.position.y<.9f,"Podium collision is floating the player");Require(player.GetComponent<PlayerMovement>().enabled&&!GameStartPresentation.BlocksGameplayInput,"Ceremony movement disabled");var movement=player.GetComponent<PlayerMovement>();typeof(PlayerMovement).GetMethod("ApplyHorizontalMovement",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(movement,new object[]{new Vector3(2,0,0)});Require(player.GetComponent<Rigidbody>().velocity.x>1,"Ceremony movement cannot drive Rigidbody");Require(final.scoreRows.All(r=>r.gameObject.activeSelf)&&final.scoreRows[0].fontSizeMax>final.scoreRows[1].fontSizeMax,"Four score rows or winner emphasis missing");Require(!Object.FindObjectsOfType<Transform>().Any(t=>t.name.StartsWith("Low survivor platform")||t.name.StartsWith("Survivor podium")),"Circular platforms remain");
 for(int i=1;i<4;i++){object[] pose={ (ulong)i,i,Vector3.zero,Quaternion.identity};typeof(FinalRanking).GetMethod("GetPresentationPose",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(final,pose);var sample=Object.Instantiate(final.characterPrefabs[i],(Vector3)pose[2],(Quaternion)pose[3]);sample.name="Validation fallen contestant "+i;foreach(var behaviour in sample.GetComponentsInChildren<MonoBehaviour>())behaviour.enabled=false;var fallen=sample.AddComponent<FinalCelebrationPlayer>();fallen.Configure(false,(Vector3)pose[2],(Quaternion)pose[3]);Require(fallen.IsFallen&&!sample.GetComponent<PlayerMovement>().enabled&&sample.GetComponent<Rigidbody>().isKinematic,"Fallen avatar can move");Require(Mathf.Abs(Vector3.Dot(sample.transform.up,Vector3.up))<.05f&&sample.transform.position.z>player.transform.position.z+2,"Non-winner is not lying behind the winner");Require(sample.GetComponentsInChildren<Collider>().All(c=>!c.enabled),"Fallen avatar collider remains active");}
 crownPosition=crown.transform.localPosition;crownRotation=crown.transform.rotation;Capture("Library/FinalRanking-preview.png");at=now;stage=6;}
 else if(stage==6){if(Time.timeSinceLevelLoad<6)return;var crown=Object.FindObjectOfType<WinnerCrown>();Require(crown!=null&&Quaternion.Angle(crownRotation,crown.transform.rotation)>10,"Crown did not rotate");Require(PartyRoster.Current.FinalReturnAt.Value-network.ServerTime.Time<15,"Return timer not synchronized");stage=7;}
 else if(stage==7){if(SceneManager.GetActiveScene().name!="Character")return;Require(now-at>=10,"Returned before 15-second celebration");Require(PartyGameRotation.PlayedCount==0&&CrosswalkRun.RankingManager.Instance.ScoreList.Count==0,"Next match state not cleared");lightIndex=0;network.SceneManager.LoadScene(lightScenes[lightIndex],LoadSceneMode.Single);stage=8;}
 else if(stage==8){if(SceneManager.GetActiveScene().name!=lightScenes[lightIndex]||Time.timeSinceLevelLoad<1.2f)return;var profile=Object.FindObjectOfType<SceneLightingProfile>();Require(profile!=null,"Original lighting profile missing");Require(RenderSettings.ambientMode==profile.ambientMode&&RenderSettings.fog==profile.fog&&RenderSettings.ambientSkyColor==profile.sky&&RenderSettings.sun==profile.sun,"Ceremony lighting leaked into "+lightScenes[lightIndex]);if(lightScenes[lightIndex]=="TileFlip"){var ui=Object.FindObjectOfType<GameStartPresentation>();Require(ui.tileTimer.text.Length==2&&ui.tileTimer.fontSize==64,"Tile seconds display incorrect");var push=Object.FindObjectOfType<PushCooldownHUD>();push.visibility.alpha=1;Capture("Library/TileFlip-refined.png");}if(++lightIndex<lightScenes.Length){network.SceneManager.LoadScene(lightScenes[lightIndex],LoadSceneMode.Single);return;}System.IO.File.WriteAllText(Result,"PASS: 5-second automatic guide and actual 1-second server start/control unlock; front winner and three rear prone pose samples; four platforms removed; final scene direct routing; owned network player movement, four rank rows and larger winner; rotating crown, 15-second return; all five original lighting profiles restored after ceremony. Local host only; four-client Relay not tested.");SessionState.SetBool(Key,false);SessionState.SetBool("Party.Finale.Restore",true);network.Shutdown();EditorApplication.isPlaying=false;Debug.Log("PARTY_FINALE_RUNTIME_PASS");}
 }catch(Exception e){Fail(e);}}
 static void Capture(string path){typeof(TicketPresentationValidation).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{path});}
 static void Prepare(){stage=0;SessionState.SetString("Party.Finale.Previous",EditorSceneManager.GetActiveScene().path);foreach(var scene in new[]{"GameBriefing","FinalRanking"}){EditorSceneManager.OpenScene("Assets/Scenes/"+scene+".unity");foreach(var root in SceneManager.GetActiveScene().GetRootGameObjects())foreach(var t in root.GetComponentsInChildren<Transform>(true))Require(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)==0,"Missing script "+t.name);foreach(var renderer in Object.FindObjectsOfType<Renderer>(true))Require(renderer.sharedMaterials.All(m=>m!=null),"Missing material");}EditorSceneManager.OpenScene("Assets/Scenes/Lobby.unity");System.IO.File.WriteAllText(Result,"RUNNING");SessionState.SetBool(Key,true);EditorApplication.isPlaying=true;}
 static void Fail(Exception e){System.IO.File.WriteAllText(Result,"FAIL: "+e);SessionState.SetBool(Key,false);if(EditorApplication.isPlaying){SessionState.SetBool("Party.Finale.Restore",true);EditorApplication.isPlaying=false;}Debug.LogException(e);}
}
#endif
